module cdc_2phase #(
  parameter WIDTH = 1
)(
  input  src_rst_ni,
  input  src_clk_i,
  input  [WIDTH-1:0] src_data_i,
  input  src_valid_i,
  output src_ready_o,
  input  dst_rst_ni,
  input  dst_clk_i,
  output [WIDTH-1:0] dst_data_o,
  output dst_valid_o,
  input  dst_ready_i
);

  logic [WIDTH-1:0] data_buf;
  logic             valid_buf;
  logic             src_ready_int;

  always_ff @(posedge src_clk_i or negedge src_rst_ni) begin
    if (!src_rst_ni) begin
      src_ready_int <= 1'b1;
      data_buf      <= '0;
      valid_buf     <= 1'b0;
    end else if (src_valid_i && src_ready_int) begin
      data_buf      <= src_data_i;
      valid_buf     <= 1'b1;
      src_ready_int <= 1'b0;
    end else if (valid_buf && dst_valid_o && dst_ready_i) begin
      src_ready_int <= 1'b1;
      valid_buf     <= 1'b0;
    end
  end

  assign src_ready_o = src_ready_int &&!dst_valid_o;

  always_ff @(posedge dst_clk_i or negedge dst_rst_ni) begin
    if (!dst_rst_ni) begin
      dst_data_o   <= '0;
      dst_valid_o  <= 1'b0;
    end else if (valid_buf &&!dst_valid_o) begin
      dst_data_o   <= data_buf;
      dst_valid_o  <= 1'b1;
    end else if (dst_valid_o && dst_ready_i) begin
      dst_valid_o  <= 1'b0;
    end
  end

endmodule
